; `blitFramebuffer 0xFF / selectVideoPage 0xFF /
;  copyVideoPage src=0x00, dst=0xFF / break / jmp self`.
; An infinite-frame-hold loop that re-blits page 0 each tick.
; Used after a cinematic completes to freeze the final image.
ENDING_HOLD_PAGE_0_INFINITE:
	blitFramebuffer 0xFF
	selectVideoPage 0xFF
	copyVideoPage src=0x00, dst=0xFF
	break
	jmp ENDING_HOLD_PAGE_0_INFINITE

LABEL_0AD7:
	blitFramebuffer 0xFF
	selectVideoPage 0xFF
	break
	jmp LABEL_0AD7

; Same shape as above but clears 0xFF to black first, then
; copies page 0x80. The "freeze-on-page-80" sibling.
ENDING_HOLD_PAGE_80_BLACK_INFINITE:
	blitFramebuffer 0xFF
	selectVideoPage 0xFF
	fill page=0xFF, color=0x00
	copyVideoPage src=0x80, dst=0xFF
	break
	jmp ENDING_HOLD_PAGE_80_BLACK_INFINITE

; Emit current framebuffer; if SCROLL_Y has wrapped past
; -200 (jg 0xFF38), jump direct to the 80-over-83 renderer;
; otherwise advance SCROLL_Y by 200 and run the 83-over-80
; renderer.
CREDITS_SCROLL_BLIT_FRAME_THEN_RENDER_83_OVER_80:
	blitFramebuffer 0xFF
	selectVideoPage 0xFF
	jg [SCROLL_Y], 0xFF38, CREDITS_SCROLL_RENDER_PAGE_80_OVER_83
	add [SCROLL_Y], 0x00C8
	jmp CREDITS_SCROLL_RENDER_PAGE_83_OVER_80

; Composite frame: copy page 80 at current SCROLL_Y, then
; page 83 at SCROLL_Y+200; break; jump back to the
; 83-over-80 blit step.
CREDITS_SCROLL_RENDER_PAGE_80_OVER_83:
	copyVideoPage src=0x80, dst=0xFF
	add [SCROLL_Y], 0x00C8
	copyVideoPage src=0x83, dst=0xFF
	sub [SCROLL_Y], 0x00C8
	break
	jmp CREDITS_SCROLL_BLIT_FRAME_THEN_RENDER_83_OVER_80

; Mirror of 0AED, but the dispatch falls to the 80-over-83
; renderer in the wrap case and to the alternate (83-over-80)
; otherwise.
CREDITS_SCROLL_BLIT_FRAME_THEN_RENDER_80_OVER_83:
	blitFramebuffer 0xFF
	selectVideoPage 0xFF
	jg [SCROLL_Y], 0xFF38, CREDITS_SCROLL_RENDER_PAGE_83_OVER_80
	add [SCROLL_Y], 0x00C8
	jmp CREDITS_SCROLL_RENDER_PAGE_80_OVER_83

; Composite frame: page 83 at SCROLL_Y, page 80 at
; SCROLL_Y+200; break; loop back to the 80-over-83 blit step.
CREDITS_SCROLL_RENDER_PAGE_83_OVER_80:
	copyVideoPage src=0x83, dst=0xFF
	add [SCROLL_Y], 0x00C8
	copyVideoPage src=0x80, dst=0xFF
	sub [SCROLL_Y], 0x00C8
	break
	jmp CREDITS_SCROLL_BLIT_FRAME_THEN_RENDER_80_OVER_83

; `fill page=1 color=0; fill page=2 color=0; selectVideoPage
;  1; blit page 1, page FF, page 2; ret`. Three-page clear-
; and-blit sequence used to reset the framebuffer chain
; between scene transitions.
CLEAR_PAGES_1_2_AND_BLIT:
	fill page=0x01, color=0x00
	fill page=0x02, color=0x00
	selectVideoPage 0x01
	blitFramebuffer 0x01
	blitFramebuffer 0xFF
	blitFramebuffer 0x02
	ret


